CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, is_admin BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL, alerts_since TIMESTAMPTZ);
CREATE TABLE property_lists (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL DEFAULT 1, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(user_id, name));
CREATE TABLE list_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, list_id BIGINT NOT NULL REFERENCES property_lists(id) ON DELETE CASCADE, source TEXT NOT NULL, source_listing_id TEXT NOT NULL, added_at TIMESTAMPTZ NOT NULL, UNIQUE(list_id, source, source_listing_id));
CREATE TABLE property_notes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL DEFAULT 1, source TEXT NOT NULL, source_listing_id TEXT NOT NULL, note TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(user_id, source, source_listing_id));
CREATE TABLE listing_workflow (user_id BIGINT NOT NULL DEFAULT 1, source TEXT NOT NULL, source_listing_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'New', contact_date TEXT, next_follow_up_date TEXT, agent_name TEXT, agent_phone TEXT, agent_email TEXT, offer_amount NUMERIC, rejection_reason TEXT NOT NULL DEFAULT '', rating INTEGER, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (user_id, source, source_listing_id));
CREATE TABLE listing_interactions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL DEFAULT 1, source TEXT NOT NULL, source_listing_id TEXT NOT NULL, kind TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', occurred_at TIMESTAMPTZ NOT NULL, next_follow_up_date TEXT);
CREATE TABLE alerts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL DEFAULT 1, source TEXT NOT NULL, source_listing_id TEXT NOT NULL, kind TEXT NOT NULL, message TEXT NOT NULL, url TEXT, created_at TIMESTAMPTZ NOT NULL, read_at TIMESTAMPTZ, UNIQUE(user_id, source, source_listing_id, kind));
CREATE TABLE smart_lists (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL DEFAULT 1, name TEXT NOT NULL, rule_json JSONB NOT NULL, is_system BOOLEAN NOT NULL DEFAULT FALSE, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(user_id, name));
CREATE TABLE searches (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL DEFAULT 1, name TEXT NOT NULL, purpose TEXT NOT NULL CHECK (purpose IN ('home', 'investment')), config_json JSONB NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(user_id, name));
CREATE TABLE runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, search_id BIGINT NOT NULL REFERENCES searches(id), config_json JSONB NOT NULL, started_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ, status TEXT NOT NULL);
CREATE TABLE source_runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id BIGINT NOT NULL REFERENCES runs(id), source TEXT NOT NULL, status TEXT NOT NULL, listing_count INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE TABLE listings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source TEXT NOT NULL, source_listing_id TEXT NOT NULL, url TEXT NOT NULL, transaction_type TEXT NOT NULL CHECK (transaction_type IN ('sale', 'rent')), first_seen_at TIMESTAMPTZ NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL, UNIQUE(source, source_listing_id));
CREATE TABLE listing_versions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, listing_id BIGINT NOT NULL REFERENCES listings(id), run_id BIGINT NOT NULL REFERENCES runs(id), observed_at TIMESTAMPTZ NOT NULL, content_hash TEXT NOT NULL, payload_json JSONB NOT NULL, UNIQUE(listing_id, content_hash));
CREATE INDEX listing_versions_listing_id_id_idx ON listing_versions(listing_id, id DESC);
CREATE INDEX listings_source_listing_id_idx ON listings(source, source_listing_id);
CREATE INDEX runs_search_id_id_idx ON runs(search_id, id DESC);
CREATE INDEX source_runs_run_id_idx ON source_runs(run_id);
